import { useId, useMemo, useState } from 'react';
import { Check, ChevronRight, Printer, Search, SlidersHorizontal } from 'lucide-react';
import {
  PRINTER_CATALOG,
  catalogConnectionHint,
  catalogModelArtwork,
  catalogSearchModels,
  getCatalogModel,
  type PrinterCatalogModel
} from '../lib/printerCatalog';
import { ListPagination, usePagedRows } from './ListPagination';
import styles from './PrinterModelPicker.module.css';

const PAGE_SIZE = 24;
const brandCollator = new Intl.Collator('ru', { sensitivity: 'base', numeric: true });
const brandCounts = new Map<string, number>();
for (const entry of PRINTER_CATALOG) brandCounts.set(entry.brand, (brandCounts.get(entry.brand) ?? 0) + 1);
const brands = [...brandCounts.keys()].sort(brandCollator.compare);

function modelName(entry: PrinterCatalogModel) {
  return entry.model.toLocaleLowerCase().startsWith(entry.brand.toLocaleLowerCase())
    ? entry.model
    : `${entry.brand} ${entry.model}`;
}

function geometryLabel(entry: PrinterCatalogModel) {
  const geometry = entry.nominalGeometry;
  return geometry ? `${geometry.x} × ${geometry.y} × ${geometry.z} мм` : undefined;
}

export function PrinterModelPicker({
  selectedId,
  onSelect,
  compact = false
}: {
  selectedId?: string;
  onSelect: (entry: PrinterCatalogModel | undefined) => void;
  compact?: boolean;
}) {
  const id = useId();
  const [query, setQuery] = useState('');
  const [brand, setBrand] = useState('');
  const selected = useMemo(() => getCatalogModel(selectedId), [selectedId]);
  const matches = useMemo(() => catalogSearchModels(query, brand || undefined), [query, brand]);
  const paged = usePagedRows(matches, `${brand}\u0000${query}`, PAGE_SIZE);
  const resetFilters = () => { setQuery(''); setBrand(''); };

  return <section className={`${styles.picker} ${compact ? styles.compact : ''}`} aria-labelledby={`${id}-title`}>
    <header className={styles.header}>
      <div><h3 id={`${id}-title`}>Выберите свой принтер</h3><p>Поиск по производителю и названию модели.</p></div>
      <span className={styles.total}>{PRINTER_CATALOG.length} моделей</span>
    </header>

    <div className={styles.filters}>
      <label className={styles.search} htmlFor={`${id}-search`}>
        <span>Поиск модели</span>
        <div><Search aria-hidden="true"/><input id={`${id}-search`} type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="Например, K1 Max или Ender-3" autoComplete="off" spellCheck={false}/></div>
      </label>
      <label className={styles.brand} htmlFor={`${id}-brand`}>
        <span>Производитель</span>
        <select id={`${id}-brand`} value={brand} onChange={event => setBrand(event.target.value)}>
          <option value="">Все производители</option>
          {brands.map(name => <option key={name} value={name}>{name} ({brandCounts.get(name)})</option>)}
        </select>
      </label>
    </div>

    <button type="button" className={styles.automatic} aria-pressed={!selected} onClick={() => onSelect(undefined)}>
      <SlidersHorizontal aria-hidden="true"/>
      <span><strong>Автоопределение / Моей модели нет</strong><small>Проверить принтер по адресу и настроить вручную.</small></span>
      {!selected ? <Check aria-hidden="true"/> : <ChevronRight aria-hidden="true"/>}
    </button>

    {selected && <div className={styles.selected} aria-live="polite" aria-atomic="true">
      <img src={catalogModelArtwork(selected)} alt="" width="72" height="72" decoding="async"/>
      <div><span className={styles.selectedLabel}><Check aria-hidden="true"/>Выбрана модель</span><strong>{modelName(selected)}</strong><small>{catalogConnectionHint(selected)}</small>{geometryLabel(selected) && <small>Заводская область: {geometryLabel(selected)}</small>}</div>
    </div>}

    <div className={styles.resultsHeading}><span role="status" aria-live="polite" aria-atomic="true">Найдено моделей: <strong>{matches.length}</strong></span>{(query || brand) && <button type="button" onClick={resetFilters}>Сбросить фильтры</button>}</div>

    {matches.length > 0 ? <ul className={styles.grid} aria-label="Модели принтеров">
      {paged.rows.map(entry => {
        const isSelected = entry.id === selectedId;
        const geometry = geometryLabel(entry);
        return <li key={entry.id}>
          <button type="button" className={styles.model} aria-pressed={isSelected} aria-label={`Выбрать ${modelName(entry)}`} onClick={() => onSelect(entry)}>
            <span className={styles.artwork}><img src={catalogModelArtwork(entry)} alt="" width="112" height="96" loading="lazy" decoding="async"/>{isSelected && <span className={styles.selectedMark}><Check aria-hidden="true"/><span>Выбрано</span></span>}</span>
            <span className={styles.modelBody}><span className={styles.modelBrand}>{entry.brand}</span><strong className={styles.modelName}>{entry.model}</strong>{geometry && <small className={styles.geometry}>Заводская область<br/>{geometry}</small>}<small className={styles.connection}>{catalogConnectionHint(entry)}</small></span>
          </button>
        </li>;
      })}
    </ul> : <div className={styles.empty}>
      <Printer aria-hidden="true"/><strong>Модель не найдена</strong><p>Попробуйте короткое название или другого производителя. Также можно выбрать автоопределение и указать адрес принтера.</p><button type="button" onClick={resetFilters}>Показать все модели</button>
    </div>}

    <div className={styles.pagination}><ListPagination count={matches.length} page={paged.page} pageSize={PAGE_SIZE} onPageChange={paged.setPage} label="Страницы моделей принтеров"/></div>
    <p className={styles.note}>Изображения работают без интернета. Если изображение модели ещё не найдено, показан силуэт. Настройки и доступные функции проверяются при подключении.</p>
  </section>;
}

import data from '../data/printerCatalog.json';
import type { KnownPrinterPreset } from '../types';
import enderKeArtwork from '../assets/ender-v3-ke-integrated-v2.png';
import enderSeArtwork from '../assets/ender-v3-se-neon-v114.png';
import k1cArtwork from '../assets/creality-k1c-clean-v1144.png';
import k1MaxArtwork from '../assets/creality-k1-max-neon-v114.png';
import adventurer5mArtwork from '../assets/flashforge-ad5m-clean-v1144.png';
import genericArtwork from '../assets/generic-klipper-printer.svg';
import { catalogArtworkById } from './printerCatalogArtwork';

export interface PrinterCatalogModel {
  id:string;
  brand:string;
  model:string;
  aliases:string[];
  sourceUrl:string;
  nominalGeometry?:{x:number;y:number;z:number};
}

const normalize=(value:string)=>value.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().replace(/ё/g,'е').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const compact=(value:string)=>normalize(value).replace(/\s/g,'');
const brandOrder=['Creality','Anycubic','Elegoo','Flashforge','Sovol','Qidi','Bambu Lab','Prusa','Voron','RatRig'];
const order=(brand:string)=>{const index=brandOrder.findIndex(value=>compact(value)===compact(brand));return index<0?brandOrder.length:index};
const collator=new Intl.Collator('ru',{sensitivity:'base',numeric:true});
const featured=['crealityk1c','crealityk1max','crealityender3v3ke','crealityender3v3se','flashforgeadventurer5m','bambulaba1','bambulabp1s','prusaoriginalprusamk4'];
const featuredOrder=(entry:PrinterCatalogModel)=>{const index=featured.indexOf(compact(`${entry.brand} ${entry.model}`));return index<0?featured.length:index};

/** Factual model identities. Presence in this index does not attest transport support. */
export const PRINTER_CATALOG:readonly PrinterCatalogModel[]=(data.models as PrinterCatalogModel[]).slice().sort((a,b)=>featuredOrder(a)-featuredOrder(b)||order(a.brand)-order(b.brand)||collator.compare(a.brand,b.brand)||collator.compare(a.model,b.model));
const byId=new Map(PRINTER_CATALOG.map(entry=>[entry.id,entry]));
export const getCatalogModel=(id:string|undefined)=>id?byId.get(id):undefined;
export const catalogModelName=(entry:PrinterCatalogModel)=>normalize(entry.model).startsWith(normalize(entry.brand))?entry.model:`${entry.brand} ${entry.model}`;

const russianAliases:Record<string,string[]>={
  creality:['креалити','креалити3д'],anycubic:['эникубик','эникьюбик','аникубик'],elegoo:['элегу','элегоо'],flashforge:['флешфордж','флэшфордж'],sovol:['совол'],qidi:['куиди','киди'],bambulab:['бамбу','бамбулаб'],prusa:['пруса'],voron:['ворон'],ratrig:['ратриг'],ultimaker:['ультимейкер'],flyingbear:['флаингбир','летающий медведь'],artillery:['артиллери'],ankermake:['анкермейк']
};
const searchIndex=PRINTER_CATALOG.map(entry=>{
  const aliases=[...(russianAliases[compact(entry.brand)]??[]),...entry.aliases];
  if(normalize(entry.model).includes('ender'))aliases.push(entry.model.replace(/ender/ig,'эндер'));
  const text=normalize([entry.brand,entry.model,...aliases].join(' '));
  return {entry,text,compact:text.replace(/\s/g,'')};
});

export function catalogSearchModels(query:string,brand?:string):PrinterCatalogModel[]{
  const words=normalize(query).split(/\s+/).filter(Boolean);
  const selectedBrand=brand?compact(brand):undefined;
  return searchIndex.filter(item=>(!selectedBrand||compact(item.entry.brand)===selectedBrand)&&words.every(word=>item.text.includes(word)||item.compact.includes(word))).map(item=>item.entry);
}

/** Exact existing artwork families; never used to select a runtime driver. */
export function getCatalogPreset(entry:PrinterCatalogModel):KnownPrinterPreset|undefined{
  const brand=compact(entry.brand),model=compact(entry.model);
  if(brand==='creality'){
    if(model==='ender3v3ke')return 'ender3-v3-ke';
    if(model==='ender3v3se')return 'ender3-v3-se';
    if(model==='k1c'||model==='k1c2025')return 'creality-k1c-2025';
    if(model==='k1max')return 'creality-k1-max';
  }
  if(brand==='flashforge'&&(model==='adventurer5m'||model==='ad5m'))return 'flashforge-ad5m';
  return undefined;
}
const artwork:Record<KnownPrinterPreset,string>={'ender3-v3-ke':enderKeArtwork,'ender3-v3-se':enderSeArtwork,'creality-k1c-2025':k1cArtwork,'creality-k1-max':k1MaxArtwork,'flashforge-ad5m':adventurer5mArtwork};
export function catalogModelArtwork(entry:PrinterCatalogModel):string{
  const preset=getCatalogPreset(entry);
  if(preset)return artwork[preset];
  return Object.hasOwn(catalogArtworkById,entry.id)?catalogArtworkById[entry.id]:genericArtwork;
}
export function catalogConnectionHint(entry:PrinterCatalogModel):string{
  const brand=compact(entry.brand);
  if(brand==='bambulab')return 'Штатное подключение Bambu пока не поддерживается';
  if(brand==='prusa')return 'Штатный PrusaLink пока не поддерживается';
  return 'Для подключения требуется доступный Klipper/Moonraker';
}

